// zod 4 migration coverage against the built binary over real stdio:
// the JSON Schemas generated by `z.toJSONSchema` still satisfy MCP client
// constraints, validation errors stay readable and short-circuit before any
// HTTP, and every tool still reaches the right Airbrake endpoint.

import { afterAll, afterEach, beforeAll, describe, expect, it } from 'vitest';
import { MockAirbrake } from './helpers/mock-airbrake.js';
import { startMcp, type McpHarness } from './helpers/mcp-harness.js';
import { allKeys } from '../helpers/json-schema.js';

type Json = Record<string, unknown>;

const SNOWFLAKE = '3741526488590376432';

const EXPECTED_ACTIONS: Record<string, string[]> = {
  airbrake_projects: ['list', 'get', 'list_activities'],
  airbrake_groups: ['list', 'get', 'get_stats', 'resolve', 'unresolve', 'mute', 'unmute', 'delete'],
  airbrake_notices: ['list', 'get', 'get_status'],
  airbrake_deploys: ['list', 'get', 'create'],
  airbrake_performance: ['routes_stats', 'queries_stats', 'queues_stats'],
  airbrake_notify: ['notify'],
  airbrake_sourcemaps: ['list', 'get', 'delete', 'upload'],
};

const PAGINATED = [
  'airbrake_projects',
  'airbrake_groups',
  'airbrake_notices',
  'airbrake_deploys',
  'airbrake_sourcemaps',
];

function actionValues(schema: Json): unknown[] {
  const action = (schema.properties as Record<string, Json>).action;
  if (action.const !== undefined) return [action.const];
  return action.enum as unknown[];
}

describe('e2e: zod 4 JSON Schema + validation', () => {
  const mock = new MockAirbrake();
  let mcp: McpHarness;
  let tools: { name: string; inputSchema: Json }[];

  beforeAll(async () => {
    await mock.start();
    mcp = await startMcp({
      AIRBRAKE_USER_TOKEN: 'e2e-token',
      AIRBRAKE_HOST: mock.url,
      AIRBRAKE_PROJECT_KEYS: JSON.stringify({ '42': 'notifier-key-42' }),
      AIRBRAKE_MAX_RETRIES: '0',
      AIRBRAKE_TIMEOUT_MS: '3000',
    });
    tools = (await mcp.client.listTools()).tools as typeof tools;
  });

  afterAll(async () => {
    await mcp?.close();
    await mock.stop();
  });

  afterEach(() => {
    try {
      mock.assertNoUnhandled();
    } finally {
      mock.reset();
    }
  });

  describe('tools/list schemas', () => {
    it('lists all 8 tools', () => {
      expect(tools.map((t) => t.name).sort()).toEqual(
        [...Object.keys(EXPECTED_ACTIONS), 'airbrake_request'].sort(),
      );
    });

    it('every inputSchema passes the MCP constraints and contains no $ref/definitions', () => {
      for (const t of tools) {
        const s = t.inputSchema;
        expect(s.type, t.name).toBe('object');
        for (const forbidden of ['anyOf', 'oneOf', 'allOf', '$ref']) {
          expect(s, `${t.name} has top-level ${forbidden}`).not.toHaveProperty(forbidden);
        }
        expect(s.additionalProperties, t.name).toBe(false);
        expect(typeof s.properties).toBe('object');
        if (s.required !== undefined) {
          expect(Array.isArray(s.required)).toBe(true);
          for (const r of s.required as unknown[]) expect(typeof r).toBe('string');
        }
        const keys = allKeys(s);
        for (const k of ['$ref', '$defs', 'definitions']) {
          expect(keys.has(k), `${t.name} contains ${k}`).toBe(false);
        }
      }
    });

    it.each(Object.entries(EXPECTED_ACTIONS))(
      '%s exposes every branch in the `action` discriminator',
      (name, actions) => {
        const t = tools.find((x) => x.name === name)!;
        expect(actionValues(t.inputSchema)).toEqual(actions);
        expect(t.inputSchema.required).toContain('action');
      },
    );

    it.each(PAGINATED)('%s keeps defaulted page/per_page optional with their defaults', (name) => {
      const s = tools.find((x) => x.name === name)!.inputSchema;
      expect(s.required).not.toContain('page');
      expect(s.required).not.toContain('per_page');
      const p = s.properties as Record<string, Json>;
      expect(p.page).toMatchObject({ type: 'integer', default: 1 });
      // Notices default to 10 per page (full backtraces); the bounds are shared.
      const perPage = name === 'airbrake_notices' ? 10 : 50;
      expect(p.per_page).toMatchObject({
        type: 'integer',
        minimum: 1,
        maximum: 200,
        default: perPage,
      });
    });

    it('snowflake IDs are advertised as digit-only strings', () => {
      const p = tools.find((x) => x.name === 'airbrake_groups')!.inputSchema.properties as Record<
        string,
        Json
      >;
      expect(p.group_id).toEqual({ type: 'string', pattern: '^\\d+$' });
      expect(p.deploy_id).toEqual({ type: 'string', pattern: '^\\d+$' });
    });

    it('airbrake_request keeps its method enum and required fields', () => {
      const s = tools.find((x) => x.name === 'airbrake_request')!.inputSchema;
      expect(s.required).toEqual(['method', 'path']);
      const p = s.properties as Record<string, Json>;
      expect(p.method.enum).toEqual(['GET', 'POST', 'PATCH', 'PUT', 'DELETE']);
      // zod 4's internal `starts_with` format is not leaked to clients.
      expect(p.path).not.toHaveProperty('format');
    });
  });

  describe('validation failures', () => {
    it('a numeric group_id returns a readable isError naming group_id, with zero HTTP', async () => {
      const res = await mcp.call('airbrake_groups', {
        action: 'get',
        project_id: 42,
        group_id: 3741526488590376,
      });
      expect(res.isError).toBe(true);
      expect(res.text).toMatch(/^Invalid arguments for airbrake_groups:/);
      expect(res.text).toMatch(/expected string, received number/);
      expect(res.text).toMatch(/at group_id/);
      expect(res.json).toBeUndefined(); // not a JSON dump of zod issues
      expect(mock.requests).toHaveLength(0);
    });

    it('an unknown action lists the valid options', async () => {
      const res = await mcp.call('airbrake_projects', { action: 'update', project_id: 1 });
      expect(res.isError).toBe(true);
      expect(res.text).toMatch(/list.*get.*list_activities/);
      expect(res.text).toMatch(/at action/);
      expect(mock.requests).toHaveLength(0);
    });

    it('an out-of-range per_page is rejected before HTTP', async () => {
      const res = await mcp.call('airbrake_projects', { action: 'list', per_page: 500 });
      expect(res.isError).toBe(true);
      expect(res.text).toMatch(/200/);
      expect(res.text).toMatch(/at per_page/);
      expect(mock.requests).toHaveLength(0);
    });
  });

  describe('happy path per tool', () => {
    const cases: {
      tool: string;
      args: Json;
      method: string;
      path: string;
      query?: Record<string, string>;
    }[] = [
      {
        tool: 'airbrake_projects',
        args: { action: 'list_activities', project_id: 42 },
        method: 'GET',
        path: '/api/v4/projects/42/activities',
        query: { page: '1', per_page: '50' },
      },
      {
        tool: 'airbrake_groups',
        args: { action: 'mute', project_id: 42, group_id: SNOWFLAKE },
        method: 'PUT',
        path: `/api/v4/projects/42/groups/${SNOWFLAKE}/muted`,
      },
      {
        tool: 'airbrake_notices',
        args: { action: 'list', project_id: 42, group_id: SNOWFLAKE, per_page: 5 },
        method: 'GET',
        path: `/api/v4/projects/42/groups/${SNOWFLAKE}/notices`,
        query: { page: '1', per_page: '5' },
      },
      {
        tool: 'airbrake_deploys',
        args: { action: 'get', project_id: 42, deploy_id: SNOWFLAKE },
        method: 'GET',
        path: `/api/v4/projects/42/deploys/${SNOWFLAKE}`,
      },
      {
        tool: 'airbrake_performance',
        args: {
          action: 'queues_stats',
          project_id: 42,
          queue: 'default',
          time__gte: '2026-01-01T00:00:00Z',
          time__lt: '2026-01-02T00:00:00Z',
          period: 'hour',
        },
        method: 'GET',
        path: '/api/v5/projects/42/queues-stats',
        query: { queue: 'default', period: 'hour' },
      },
      {
        tool: 'airbrake_notify',
        args: {
          action: 'notify',
          project_id: 42,
          payload: { errors: [{ type: 'Error', message: 'boom' }], context: { env: 'e2e' } },
        },
        method: 'POST',
        path: '/api/v3/projects/42/notices',
        query: { key: 'notifier-key-42' },
      },
      {
        tool: 'airbrake_sourcemaps',
        args: { action: 'delete', project_id: 42, sourcemap_id: '77' },
        method: 'DELETE',
        path: '/api/v4/projects/42/sourcemaps/77',
      },
      {
        tool: 'airbrake_request',
        args: { method: 'GET', path: '/api/v4/projects/42', query: { verbose: true } },
        method: 'GET',
        path: '/api/v4/projects/42',
        query: { verbose: 'true' },
      },
    ];

    it.each(cases)('$tool reaches $method $path', async ({ tool, args, method, path, query }) => {
      mock.on(method, path, { body: { ok: true } });
      const res = await mcp.call(tool, args);
      expect(res.isError, res.text).toBe(false);
      const hits = mock.find(method, path);
      expect(hits).toHaveLength(1);
      expect(mock.requests).toHaveLength(1);
      if (query) expect(hits[0].query).toMatchObject(query);
    });

    it('airbrake_notify forwards passthrough (loose) payload keys unchanged', async () => {
      mock.on('POST', '/api/v3/projects/42/notices', { status: 201, body: { id: 'x' } });
      const payload = {
        errors: [{ type: 'E', message: 'm' }],
        context: { a: 1 },
        params: { b: 2 },
      };
      const res = await mcp.call('airbrake_notify', { action: 'notify', project_id: 42, payload });
      expect(res.isError).toBe(false);
      const [req] = mock.find('POST', '/api/v3/projects/42/notices');
      expect(JSON.parse(req!.body)).toEqual(payload);
    });

    it('airbrake_deploys create forwards record fields at the top level of the body', async () => {
      mock.on('POST', '/api/v4/projects/42/deploys', { status: 201, body: { id: '1' } });
      const deploy = { environment: 'production', revision: 'abc', version: '1.2.3' };
      const res = await mcp.call('airbrake_deploys', { action: 'create', project_id: 42, deploy });
      expect(res.isError).toBe(false);
      const [req] = mock.find('POST', '/api/v4/projects/42/deploys');
      expect(JSON.parse(req!.body)).toEqual(deploy);
    });
  });
});
